// 1. Input Validation
if (gv_input.enable != 0 && gv_input.enable != 1) {
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s.x = 0.0;
    gv_output.voted_rate_rad_s.y = 0.0;
    gv_output.voted_rate_rad_s.z = 0.0;
    return;
}

for (int i = 0; i < 3; i++) {
    if (gv_input.gyro[i] == NULL || !adcs_is_finite_vec3(gv_input.gyro[i])) {
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s.x = 0.0;
        gv_output.voted_rate_rad_s.y = 0.0;
        gv_output.voted_rate_rad_s.z = 0.0;
        return;
    }
}

if (!isfinite(gv_config.threshold_rad_s) || gv_config.threshold_rad_s < 0.0 ||
    !isfinite(gv_config.reentry_threshold_rad_s) || gv_config.reentry_threshold_rad_s < 0.0 ||
    gv_config.reentry_threshold_rad_s > gv_config.threshold_rad_s ||
    gv_config.isolate_confirm < 1 || gv_config.isolate_confirm > 20 ||
    gv_config.reentry_confirm < 1 || gv_config.reentry_confirm > 20) {
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s.x = 0.0;
    gv_output.voted_rate_rad_s.y = 0.0;
    gv_output.voted_rate_rad_s.z = 0.0;
    return;
}

// 2. Disable Handling: Reset State
if (gv_input.enable == 0) {
    for (int i = 0; i < 3; i++) {
        gv_state.bad_streak[i] = 0;
        gv_state.good_streak[i] = 0;
        gv_state.isolated[i] = 0;
    }
    // Still compute distances and mask as per "Report... regardless"
    // But Mode will be set to OFF at the end
}

// 3. Compute Component-wise Median
double med[3];
double vals[3];
for (int dim = 0; dim < 3; dim++) {
    for (int i = 0; i < 3; i++) {
        if (dim == 0) vals[i] = gv_input.gyro[i]->x;
        else if (dim == 1) vals[i] = gv_input.gyro[i]->y;
        else vals[i] = gv_input.gyro[i]->z;
    }
    // Sort 3 values
    if (vals[0] > vals[1]) { double t = vals[0]; vals[0] = vals[1]; vals[1] = t; }
    if (vals[1] > vals[2]) { double t = vals[1]; vals[1] = vals[2]; vals[2] = t; }
    if (vals[0] > vals[1]) { double t = vals[0]; vals[0] = vals[1]; vals[1] = t; }
    med[dim] = vals[1];
}
adcs_vec3_t median = {med[0], med[1], med[2]};

// 4. Compute Distances and Outlier Mask & Update Isolation
unint32 outlier_mask = 0;
int outlier_count = 0;
int isolated_count = 0;
int non_iso_indices[3];
int non_iso_count = 0;

for (int i = 0; i < 3; i++) {
    adcs_vec3_t diff = adcs_vec3_sub(gv_input.gyro[i], &median);
    double dist = adcs_vec3_norm(&diff);
    gv_output.distance_rad_s[i] = dist;

    int is_outlier = (dist > gv_config.threshold_rad_s);
    if (is_outlier) {
        outlier_mask |= (1U << i);
        outlier_count++;
    }

    // Update Isolation State
    if (gv_state.isolated[i]) {
        // Isolated: check against reentry threshold
        int is_good = (dist <= gv_config.reentry_threshold_rad_s);
        if (is_good) {
            gv_state.good_streak[i]++;
            if (gv_state.good_streak[i] >= gv_config.reentry_confirm) {
                gv_state.isolated[i] = 0;
                gv_state.good_streak[i] = 0;
                gv_state.bad_streak[i] = 0;
            }
        } else {
            gv_state.good_streak[i] = 0;
        }
    } else {
        // Not isolated: check against normal threshold
        if (is_outlier) {
            gv_state.bad_streak[i]++;
            if (gv_state.bad_streak[i] >= gv_config.isolate_confirm) {
                gv_state.isolated[i] = 1;
                // Bad streak remains at isolate_confirm value effectively, 
                // but logically it triggered the latch.
                // Good streak starts at 0.
            }
        } else {
            gv_state.bad_streak[i] = 0;
        }
    }

    if (gv_state.isolated[i]) {
        isolated_count++;
    } else {
        non_iso_indices[non_iso_count++] = i;
    }
}

// 5. Voting Logic
if (gv_input.enable == 0) {
    gv_output.mode = GV_OFF;
    gv_output.voted_rate_rad_s.x = 0.0;
    gv_output.voted_rate_rad_s.y = 0.0;
    gv_output.voted_rate_rad_s.z = 0.0;
} else if (isolated_count >= 2) {
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s.x = 0.0;
    gv_output.voted_rate_rad_s.y = 0.0;
    gv_output.voted_rate_rad_s.z = 0.0;
} else if (isolated_count == 1) {
    if (non_iso_count == 2) {
        adcs_vec3_t diff = adcs_vec3_sub(gv_input.gyro[non_iso_indices[0]], gv_input.gyro[non_iso_indices[1]]);
        double mutual_dist = adcs_vec3_norm(&diff);
        if (mutual_dist <= gv_config.threshold_rad_s) {
            adcs_vec3_t sum = adcs_vec3_add(gv_input.gyro[non_iso_indices[0]], gv_input.gyro[non_iso_indices[1]]);
            gv_output.voted_rate_rad_s = adcs_vec3_scale(&sum, 0.5);
            gv_output.mode = GV_DEGRADED;
        } else {
            gv_output.mode = GV_FAULT;
            gv_output.voted_rate_rad_s.x = 0.0;
            gv_output.voted_rate_rad_s.y = 0.0;
            gv_output.voted_rate_rad_s.z = 0.0;
        }
    } else {
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s.x = 0.0;
        gv_output.voted_rate_rad_s.y = 0.0;
        gv_output.voted_rate_rad_s.z = 0.0;
    }
} else { // isolated_count == 0
    if (outlier_count == 0) {
        gv_output.voted_rate_rad_s = median;
        gv_output.mode = GV_NOMINAL;
    } else if (outlier_count == 1) {
        adcs_vec3_t sum = adcs_vec3_add(gv_input.gyro[non_iso_indices[0]], gv_input.gyro[non_iso_indices[1]]);
        gv_output.voted_rate_rad_s = adcs_vec3_scale(&sum, 0.5);
        gv_output.mode = GV_DEGRADED;
    } else { // outlier_count >= 2
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s.x = 0.0;
        gv_output.voted_rate_rad_s.y = 0.0;
        gv_output.voted_rate_rad_s.z = 0.0;
    }
}

gv_output.outlier_mask = outlier_mask;

