    if (gv_state.isolated[i]) {
        isolated_count++;
    } else {
        non_isolated_indices[ni_count++] = i;
    }
}

// 7. Voting Logic
adcs_vec3_t zero_vec = {0.0, 0.0, 0.0};

if (isolated_count == 0) {
    if (outlier_count == 0) {
        gv_output.mode = GV_NOMINAL;
        gv_output.voted_rate_rad_s = median_vec;
    } else if (outlier_count == 1) {
        gv_output.mode = GV_DEGRADED;
        adcs_vec3_t sum = {0.0, 0.0, 0.0};
        for (int i = 0; i < 3; i++) {
            if (!(outlier_mask & (1U << i))) {
                sum = adcs_vec3_add(&sum, gv_input.gyro[i]);
            }
        }
        gv_output.voted_rate_rad_s = adcs_vec3_scale(&sum, 0.5);
    } else {
        // 2 or 3 outliers
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s = zero_vec;
    }
} else if (isolated_count == 1) {
    if (ni_count == 2) {
        adcs_vec3_t diff = adcs_vec3_sub(gv_input.gyro[non_isolated_indices[0]], gv_input.gyro[non_isolated_indices[1]]);
        double dist_ij = adcs_vec3_norm(&diff);

        if (dist_ij <= gv_config.threshold_rad_s) {
            gv_output.mode = GV_DEGRADED;
            adcs_vec3_t sum = adcs_vec3_add(gv_input.gyro[non_isolated_indices[0]], gv_input.gyro[non_isolated_indices[1]]);
            gv_output.voted_rate_rad_s = adcs_vec3_scale(&sum, 0.5);
        } else {
            gv_output.mode = GV_FAULT;
            gv_output.voted_rate_rad_s = zero_vec;
        }
    } else {
        gv_output.mode = GV_FAULT;
        gv_output.voted_rate_rad_s = zero_vec;
    }
} else {
    // 2 or 3 isolated
    gv_output.mode = GV_FAULT;
    gv_output.voted_rate_rad_s = zero_vec;
}
